SELECT 'gongkao', '多定义判断概述', 'kp-xc-definition-multi-overview', CAST($${"type":"doc","content":[{"type":"heading","attrs":{"level":1},"content":[{"type":"text","text":"多定义判断概述"}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#fffbeb","borderColor":"#f59e0b","icon":"💡"},"content":[{"type":"paragraph","content":[{"type":"text","text":"识别特征：","marks":[{"type":"bold"}]},{"type":"text","text":"题干给出多个定义，要求区分或匹配。约占定义判断的 20%。核心方法和单定义一样，多了一个「区分比较」的步骤。"}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"一、包含的子类"}]},{"type":"columns","attrs":{"cols":2},"content":[{"type":"column","attrs":{"index":0},"content":[{"type":"paragraph","content":[{"type":"text","text":"子类","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"区别型：给出多个定义，问其中一个"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"匹配型：给出多个定义和多个例子，要求匹配"}]}]}]}]},{"type":"column","attrs":{"index":1},"content":[{"type":"paragraph","content":[{"type":"text","text":"考频","marks":[{"type":"bold"}]}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"区别型：约 710 题（高频）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"匹配型：约 90 题（低频）"}]}]}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"二、核心判断逻辑"}]},{"type":"textDiagram","attrs":{"language":"mermaid"},"content":[{"type":"text","text":"flowchart TD\n    A[多个定义] --> B{问的是哪个定义?}\n    B -->|只问一个| C[区别型]\n    B -->|要求匹配| D[匹配型]\n    C --> E[锁定目标定义]\n    E --> F[用单定义方法解题]\n    D --> G[逐个定义找关键词]\n    G --> H[对号入座排除落单]"}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"三、与单定义的区别"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"区别型 = 单定义 + 区分干扰定义（先排除其他定义的干扰）"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"匹配型 = 多个单定义同时进行（效率要求更高）"}]}]}]},{"type":"highlightBlock","attrs":{"backgroundColor":"#eff6ff","borderColor":"#3b82f6","icon":"📊"},"content":[{"type":"paragraph","content":[{"type":"text","text":"学习建议：","marks":[{"type":"bold"}]},{"type":"text","text":"多定义判断的解题方法和单定义完全一样，只是多了一步「区分」。先学好单定义，再学多定义就很容易。"}]}]}]}$$ AS jsonb), NULL, '多定义判断概述：区别型与匹配型的识别特征、判断逻辑。', category_node.id, CAST('["定义判断", "多定义", "概述"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_judgement_definition_multi", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
